('hollow-body-hold', 'Hollow Body Hold', 'Core', ARRAY['Core','Hip Flexors']::text[], ARRAY[]::text[], ARRAY['floor']::text[], '["Lower back glued to floor","Ribs pulled down","Arms by ears, biceps covering"]'::jsonb, 2, 'The hollow body is the shape that transfers to handstands, levers, and planche. Master this first.', NULL, 'https://www.youtube.com/watch?v=44ScXWFaVBs', NULL, 'public'),
('plank', 'Plank', 'Core', ARRAY['Core','Shoulders']::text[], ARRAY[]::text[], ARRAY['floor']::text[], '["Squeeze glutes","Pull elbows toward toes","Breathe behind the brace"]'::jsonb, 2, 'Forearm plank with intent. Squeeze everything—this is practice for maintaining tension under load.', NULL, 'https://www.youtube.com/watch?v=ASdvN_XEl_c', NULL, 'public'),
('l-sit', 'L-Sit', 'Core', ARRAY['Core','Hip Flexors','Triceps']::text[], ARRAY[]::text[], ARRAY['floor','parallettes']::text[], '["Depress shoulders hard","Point toes","Push floor away"]'::jsonb, 3, 'A fundamental static hold that develops incredible core strength and hip flexor endurance.', NULL, 'https://www.youtube.com/watch?v=cu0fHp8HCDo', NULL, 'public'),
