('hanging-leg-raise', 'Hanging Leg Raise', 'Core', ARRAY['Core','Hip Flexors','Grip']::text[], ARRAY[]::text[], ARRAY['pull-up bar']::text[], '["Dead hang start","Legs straight","Control the descent"]'::jsonb, 3, 'Hang from a bar, raise straight legs to horizontal or above. No swinging.', NULL, 'https://www.youtube.com/watch?v=Pr1ieGZ5atk', NULL, 'public'),
('bodyweight-squat', 'Bodyweight Squat', 'Legs', ARRAY['Quadriceps','Glutes','Core']::text[], ARRAY[]::text[], ARRAY['floor']::text[], '["Feet shoulder width","Knees track toes","Full depth"]'::jsonb, 2, 'Full depth squat with control. Heels stay planted, chest stays tall.', NULL, 'https://www.youtube.com/watch?v=cB0cOX7gePg', NULL, 'public'),
('bulgarian-split-squat', 'Bulgarian Split Squat', 'Legs', ARRAY['Quadriceps','Glutes','Hip Flexors']::text[], ARRAY[]::text[], ARRAY['floor','chair']::text[], '["Upright torso","Front knee over toes","Control the bottom"]'::jsonb, 1, 'Rear foot elevated on a bench. Drop the back knee straight down.', NULL, 'https://www.youtube.com/watch?v=jWD8_iBkND0', NULL, 'public'),
('calf-raise', 'Calf Raise', 'Legs', ARRAY['Calves']::text[], ARRAY[]::text[], ARRAY['floor']::text[], '["Full range of motion","Pause at top","Slow negative"]'::jsonb, 2, 'Single or double leg. Full range: heel below toes to max plantar flexion.', NULL, NULL, NULL, 'public'),
