('cat-cow-stretch', 'Cat-Cow Stretch', 'Yoga', ARRAY['Spine','Core']::text[], ARRAY[]::text[], ARRAY['floor']::text[], '["Inhale: arch","Exhale: round","Move one vertebra at a time"]'::jsonb, 2, 'Flow between spinal flexion and extension. Breath-driven, slow.', NULL, 'https://www.youtube.com/watch?v=kqnua4rHVVA', NULL, 'public'),
