('downward-dog', 'Downward Dog', 'Yoga', ARRAY['Shoulders','Hamstrings','Calves']::text[], ARRAY[]::text[], ARRAY['floor']::text[], '["Push floor away","Externally rotate arms","Pedal heels"]'::jsonb, 2, 'Inverted V shape. Push hips high, heels toward floor. Active shoulders.', NULL, 'https://www.youtube.com/watch?v=j97SSGsnCAQ', NULL, 'public'),
