('forearm-stand-line-hold', 'Forearm Stand Line Holds', 'Skills', ARRAY['Shoulders','Core','Traps','Serratus']::text[], ARRAY[]::text[], ARRAY['floor']::text[], '["Stack hips over shoulders","Push forearms into floor","Squeeze glutes to close the line"]'::jsonb, 4, 'A straight-line forearm stand held away from the wall. The culmination of Pincha training—demands shoulder stability and refined balance.', NULL, NULL, NULL, 'public'),
('elbow-stand-wall-hold', 'Elbow Stand Wall Holds', 'Skills', ARRAY['Triceps','Shoulders','Core']::text[], ARRAY[]::text[], ARRAY['wall']::text[], '["Hands flat, elbows bent","Weight in palms and forearms","Core tight, ribs in"]'::jsonb, 1, 'Practice an elbow stand against a wall to build the tricep strength and balance awareness needed for freestanding elbow stands.', NULL, 'https://www.youtube.com/watch?v=HXVtKWV_sKY', NULL, 'public'),
('elbow-stand-straddle-entry', 'Elbow Stand Straddle Entry', 'Skills', ARRAY['Triceps','Shoulders','Core','Hip Flexors']::text[], ARRAY[]::text[], ARRAY['floor']::text[], '["Straddle wide on kick","Press through palms","Stack hips then close legs"]'::jsonb, 3, 'A straddle-leg entry into elbow stand that develops control and reduces the momentum needed compared to a straight-leg kick.', NULL, 'https://www.youtube.com/watch?v=FtTzceXNMPw', NULL, 'public'),
('elbow-stand-exit', 'Elbow Stand Exits', 'Skills', ARRAY['Triceps','Shoulders','Core']::text[], ARRAY[]::text[], ARRAY['floor']::text[], '["Tuck chin on exit","Roll through upper back","Control the descent speed"]'::jsonb, 3, 'Learn to safely exit an elbow stand by rolling out or stepping down. Protects the face and neck and builds confidence for longer holds.', NULL, NULL, NULL, 'public'),
('dead-hang', 'Dead Hang', 'Pull', ARRAY['Grip','Forearms','Shoulders']::text[], ARRAY[]::text[], ARRAY['pull-up bar']::text[], '["Full grip around bar","Relax shoulders (passive) or depress (active)","Breathe normally"]'::jsonb, 2, 'Hang from a bar with relaxed shoulders (passive) or depressed shoulders (active). Builds grip endurance and decompresses the spine.', NULL, 'https://www.youtube.com/watch?v=fq9gDvNZQ2c', NULL, 'public'),
('towel-hang', 'Towel Hang', 'Pull', ARRAY['Grip','Forearms','Shoulders']::text[], ARRAY[]::text[], ARRAY['pull-up bar','towel']::text[], '["Grip towel tightly","Shoulders depressed","No swinging"]'::jsonb, 1, 'Hang from a towel draped over a pull-up bar. The thick, pliable surface forces forearms to work significantly harder than a standard bar hang.', NULL, 'https://www.youtube.com/watch?v=UpP-77-GeLA', NULL, 'public'),
('extensor-band', 'Extensor Band Exercises', 'Mobility', ARRAY['Forearm Extensors','Fingers']::text[], ARRAY[]::text[], ARRAY['resistance band']::text[], '["Spread fingers against band","Full extension each rep","Controlled tempo"]'::jsonb, 2, 'Use finger extensor bands to strengthen the often-neglected forearm extensors. Prevents imbalances from heavy grip work and reduces elbow injury risk.', NULL, NULL, NULL, 'public'),
('seated-pike-lift', 'Seated Pike Compression Lifts', 'Core', ARRAY['Hip Flexors','Core','Quadriceps']::text[], ARRAY[]::text[], ARRAY['floor']::text[], '["Knees locked straight","Chest tall, lean slightly forward","Lift from hip flexors"]'::jsonb, 1, 'Seated with legs together and straight, lift both feet off the floor using hip flexors. Builds the active compression needed for L-sit and press handstand.', NULL, 'https://www.youtube.com/watch?v=3f6tRHAsjFo', NULL, 'public'),
('lunge', 'Lunges', 'Legs', ARRAY['Quadriceps','Glutes','Hip Flexors']::text[], ARRAY[]::text[], ARRAY['floor']::text[], '["Step length allows 90° at both knees","Upright torso","Control the descent"]'::jsonb, 2, 'Forward or reverse lunge with control. Develops single-leg strength, balance, and hip stability as a foundation for pistol and shrimp squat progressions.', NULL, NULL, NULL, 'public'),
('cossack-squat', 'Cossack Squat', 'Legs', ARRAY['Quadriceps','Adductors','Glutes','Hip Flexors']::text[], ARRAY[]::text[], ARRAY['floor']::text[], '["Heel down on working leg","Chest up","Straight leg toes point up"]'::jsonb, 1, 'A deep side-to-side squat that develops hip mobility, adductor flexibility, and single-leg strength. Essential for well-rounded lower body development.', NULL, 'https://www.youtube.com/watch?v=JaCbmoDqUc4', NULL, 'public'),
('wall-compression-stretch', 'Wall Compression Stretch', 'Core', ARRAY['Hip Flexors','Core','Hamstrings']::text[], ARRAY[]::text[], ARRAY['wall']::text[], '["Chest to thighs","Straight legs against wall","Breathe into the fold"]'::jsonb, 1, 'Face a wall, place feet up the wall and actively compress chest to thighs. Builds the deep pike compression needed for press to handstand.', NULL, NULL, NULL, 'public'),
('elevated-chair-compression', 'Elevated Chair Compression Drill', 'Core', ARRAY['Hip Flexors','Core','Shoulders']::text[], ARRAY[]::text[], ARRAY['chair']::text[], '["Depress shoulders on blocks","Squeeze legs to chest","Lift hips above shoulders"]'::jsonb, 3, 'Hands on a chair/blocks, actively compress and lift legs in pike or straddle. The elevated surface allows deeper compression range.', NULL, NULL, NULL, 'public'),
('crocodile-pose', 'Crocodile Pose (One-Arm Balance)', 'Skills', ARRAY['Core','Shoulders','Wrists','Obliques']::text[], ARRAY[]::text[], ARRAY['floor']::text[], '["Elbow in hip crease","Extend legs back and to side","Lean until you float"]'::jsonb, 3, 'A one-arm balance where the body extends laterally like a crocodile. Demands wrist strength, oblique engagement, and fearless lean.', NULL, NULL, NULL, 'public'),
('hspu-capacity-builder', 'HSPU Capacity Builder', 'Push', ARRAY['Shoulders','Triceps','Core','Traps']::text[], ARRAY[]::text[], ARRAY['wall']::text[], '["Slow eccentrics (3–5s down)","Pause at bottom","Press through full ROM"]'::jsonb, 3, 'Wall-supported partial-range handstand push-up drills focusing on building pressing capacity. Eccentric-focused negatives and pause reps.', NULL, NULL, NULL, 'public'),
('band-assisted-progressions', 'Band-Assisted Progressions', 'Push', ARRAY['Shoulders','Core','Chest']::text[], ARRAY[]::text[], ARRAY['resistance band','floor']::text[], '["Band at hips for support","Maintain proper form despite assistance","Gradually reduce band tension"]'::jsonb, 2, 'Resistance band assistance for planche leans, front lever attempts, and other advanced holds. Allows proper form practice before full bodyweight.', NULL, NULL, NULL, 'public'),
('straddle-press-to-hs', 'Straddle Press to Handstand', 'Skills', ARRAY['Shoulders','Core','Hip Flexors','Hamstrings']::text[], ARRAY[]::text[], ARRAY['floor']::text[], '["Lean forward as hips rise","Straight arms throughout","Straddle legs until vertical then close"]'::jsonb, 4, 'From standing straddle, fold forward, place hands, and press up through a straddle to handstand with straight arms. The ultimate compression strength demonstration.', NULL, 'https://www.youtube.com/watch?v=-xPx6-rbcfs', NULL, 'public'),
('stalder-press-to-hs', 'Stalder Press to Handstand', 'Skills', ARRAY['Shoulders','Core','Hip Flexors','Adductors']::text[], ARRAY[]::text[], ARRAY['floor']::text[], '["Start from floor straddle","Lean hard forward","Compress and lift without momentum"]'::jsonb, 5, 'From a seated straddle on the floor, press to handstand without jumping. Requires extreme compression strength and shoulder leverage. The pinnacle of press handstand mastery.', NULL, 'https://www.youtube.com/watch?v=S4QLsLT2wx8', NULL, 'public'),
('childs-pose', 'Child''s Pose', 'Yoga', ARRAY['Spine','Hips','Shoulders']::text[], ARRAY[]::text[], ARRAY['floor']::text[], '["Knees together or wide","Hips to heels","Forehead to floor"]'::jsonb, 2, 'Kneel, sit back on heels, fold forward with arms extended. The universal rest and reset position.', NULL, NULL, NULL, 'public'),
('warrior-i', 'Warrior I (Virabhadrasana I)', 'Yoga', ARRAY['Quadriceps','Hip Flexors','Shoulders','Core']::text[], ARRAY[]::text[], ARRAY['floor']::text[], '["Back foot at 45°","Front knee over ankle","Arms reach high, shoulders down"]'::jsonb, 2, 'Deep lunge with back foot angled, arms reaching overhead. Builds leg strength and hip flexibility.', NULL, 'https://www.youtube.com/watch?v=k4qaVoAbeHM', NULL, 'public'),
('warrior-ii', 'Warrior II (Virabhadrasana II)', 'Yoga', ARRAY['Quadriceps','Hips','Shoulders','Core']::text[], ARRAY[]::text[], ARRAY['floor']::text[], '["Front knee tracks over toes","Arms level, shoulders relaxed","Gaze past front hand"]'::jsonb, 2, 'Wide stance, front knee bent, arms extended parallel to floor. Gaze over front fingers.', NULL, 'https://www.youtube.com/watch?v=QMr0JJfEgbM', NULL, 'public'),
('warrior-iii', 'Warrior III (Virabhadrasana III)', 'Yoga', ARRAY['Hamstrings','Glutes','Core','Shoulders']::text[], ARRAY[]::text[], ARRAY['floor']::text[], '["Hips level and square","Back leg active","Core engaged, no arching"]'::jsonb, 3, 'Standing on one leg, torso and back leg form a T-shape. Arms extend forward or alongside body.', NULL, 'https://www.youtube.com/watch?v=t-VgOxS9zRQ', NULL, 'public'),
('tree-pose', 'Tree Pose (Vrksasana)', 'Yoga', ARRAY['Core','Hips','Ankles','Glutes']::text[], ARRAY[]::text[], ARRAY['floor']::text[], '["Foot presses into thigh, thigh presses back","Hips level","Gaze fixed on one point"]'::jsonb, 2, 'Stand on one leg, place other foot on inner thigh or calf (never the knee). Hands at heart or overhead.', NULL, 'https://www.youtube.com/watch?v=yVE4XXFFO70', NULL, 'public'),
('chair-pose', 'Chair Pose (Utkatasana)', 'Yoga', ARRAY['Quadriceps','Glutes','Core','Shoulders']::text[], ARRAY[]::text[], ARRAY['floor']::text[], '["Weight in heels","Knees behind toes","Arms by ears, shoulders down"]'::jsonb, 1, 'Sit back as if into a chair, arms reaching overhead. Builds leg endurance and core stability.', NULL, 'https://www.youtube.com/watch?v=semq253gJOc', NULL, 'public'),
('triangle-pose', 'Triangle Pose (Trikonasana)', 'Yoga', ARRAY['Hamstrings','Obliques','Hips','Shoulders']::text[], ARRAY[]::text[], ARRAY['floor']::text[], '["Hinge from hip, not waist","Both arms in one line","Gaze up at top hand"]'::jsonb, 1, 'Wide stance, hinge at hip to reach one hand toward foot while other arm reaches skyward. Opens the entire side body.', NULL, 'https://www.youtube.com/watch?v=S6gB0QHbWFE', NULL, 'public'),
('crow-pose', 'Crow Pose (Bakasana)', 'Yoga', ARRAY['Core','Shoulders','Wrists','Hip Flexors']::text[], ARRAY[]::text[], ARRAY['floor']::text[], '["Knees on backs of arms","Lean forward until feet lift","Gaze slightly forward"]'::jsonb, 3, 'Squat, place hands on floor, lean forward and lift feet. The gateway arm balance that connects yoga to planche progression.', NULL, 'https://www.youtube.com/watch?v=Pu3KsHHM2II', NULL, 'public'),
('half-moon-pose', 'Half Moon Pose (Ardha Chandrasana)', 'Yoga', ARRAY['Glutes','Core','Hamstrings','Ankles']::text[], ARRAY[]::text[], ARRAY['floor']::text[], '["Stack hips vertically","Flex lifted foot","Gaze up at top hand"]'::jsonb, 3, 'Balance on one leg with torso and lifted leg parallel to floor, top arm reaching skyward. Demands balance, hip opening, and core stability.', NULL, 'https://www.youtube.com/watch?v=pMoBDGa_BT0', NULL, 'public'),
('wheel-pose', 'Wheel Pose (Urdhva Dhanurasana)', 'Yoga', ARRAY['Spine','Shoulders','Glutes','Quadriceps']::text[], ARRAY[]::text[], ARRAY['floor']::text[], '["Push through hands and feet","Straighten arms","Press chest through arms"]'::jsonb, 4, 'Full back bridge pushing up from floor. Demands shoulder mobility, spinal extension, and hip flexor openness. The advanced expression of bridge pose.', NULL, 'https://www.youtube.com/watch?v=ViPnKbrc_bI', NULL, 'public'),
('camel-pose', 'Camel Pose (Ustrasana)', 'Yoga', ARRAY['Spine','Hip Flexors','Chest','Shoulders']::text[], ARRAY[]::text[], ARRAY['floor']::text[], '["Push hips forward over knees","Lift chest before arching","Head follows the arc naturally"]'::jsonb, 1, 'Kneel, place hands on heels, and push hips forward while arching back. Opens the entire front body.', NULL, 'https://www.youtube.com/watch?v=VPp5n2MZO4c', NULL, 'public'),
('press-hs-journey', 'Press Handstand Journey Drills', 'Core', ARRAY['Hip Flexors','Core','Shoulders']::text[], ARRAY[]::text[], ARRAY['floor']::text[], '["Focus on compression, not momentum","Straight arms always","Quality over quantity"]'::jsonb, 3, 'A collection of drills combining pike compression, straddle lifts, and wall walks to build the specific strength for press to handstand.', NULL, NULL, NULL, 'public'),
