('middle-split-hold', 'Middle Split Hold', 'Mobility', ARRAY['Adductors','Hamstrings','Hip Flexors']::text[], ARRAY[]::text[], ARRAY['floor']::text[], '["Slide feet out gradually","Keep hips square","Breathe and relax into depth"]'::jsonb, 4, 'Isometric hold in the full middle split position. Made iconic by Jean-Claude Van Damme. The pinnacle of hip adductor flexibility.', NULL, 'https://www.youtube.com/watch?v=0MJl4DjEMCE', NULL, 'public'),
('releve', 'Relevé', 'Flexibility', ARRAY['Calves','Ankles','Core']::text[], ARRAY[]::text[], ARRAY['floor']::text[], '["Weight over big toe","Squeeze inner thighs","Crown of head lifts"]'::jsonb, 2, 'Stand tall, rise onto the balls of your feet with control, hold, and lower. Foundation for all ballet balance.', NULL, 'https://www.youtube.com/watch?v=unv8TS3JO6U', NULL, 'public'),
('first-position-plie', 'First Position Plié', 'Flexibility', ARRAY['Quads','Glutes','Inner Thighs','Calves']::text[], ARRAY[]::text[], ARRAY['floor']::text[], '["Knees track over toes","Tailbone drops straight down","Heels stay grounded"]'::jsonb, 2, 'Heels together, toes turned out. Bend knees over toes and rise with control. The most fundamental ballet movement.', NULL, 'https://www.youtube.com/watch?v=DrBhcopjDZQ', NULL, 'public'),
